set-variable.value:
@{
                                  var opLocation = (string)context.Variables["backendOperationLocation"];

                                  if (string.IsNullOrEmpty(opLocation))
                                  {
                                      return string.Empty;
                                  }

                                  var resultPart = opLocation.Split('/').Last();

                                  if (resultPart.Contains("?"))
                                  {
                                      return resultPart.Split('?')[0];
                                  }

                                  return resultPart;
                              }

set-header.value:
@{
                        var host = context.Request.OriginalUrl.Host.Replace("-int", "");
                        var apiPath = context.Api.Path.Trim('/');
                        var modelId = (string)context.Variables["modelId"];
                        var resultId = (string)context.Variables["resultId"];
                        var apiVersion = ((string)context.Variables["apiVersion"]).Trim('/');

                        return $"https://{host}/{apiPath}/{context.Api.Version}/documentintelligence/documentModels/{modelId}/analyzeResults/{resultId}?api-version={apiVersion}";
                    }
